"use strict";(self.webpackChunktemp_docusaurus=self.webpackChunktemp_docusaurus||[]).push([["632"],{8399(e,a,o){o.r(a),o.d(a,{metadata:()=>n,default:()=>u,frontMatter:()=>c,contentTitle:()=>s,toc:()=>t,assets:()=>i});var n=JSON.parse('{"id":"practica-4","title":"Practica 4: Navegaci\xf3n global con algoritmo GPP, plan como recurso","description":"El objetivo de la pr\xe1ctica es implementar la l\xf3gica de navegaci\xf3n global de un coche aut\xf3nomo que se mueve por un mapa de ciudad. Cuando el usuario selecciona un destino haciendo clic en el mapa, el algoritmo de planificaci\xf3n debe encontrar el camino m\xe1s corto hasta \xe9l, evitando todo lo que no sea carretera, y el robot debe seguir ese camino de forma aut\xf3noma hasta llegar. Para ello se utiliza el m\xe9todo Gradient Path Planning (GPP)","source":"@site/docs/Practica4.md","sourceDirName":".","slug":"/practica-4","permalink":"/docs/practica-4","draft":false,"unlisted":false,"tags":[],"version":"current","sidebarPosition":4,"frontMatter":{"id":"practica-4","title":"Practica 4: Navegaci\xf3n global con algoritmo GPP, plan como recurso","sidebar_position":4},"sidebar":"tutorialSidebar","previous":{"title":"Practica 3: Navegaci\xf3n local esquivando obst\xe1culos con algoritmo VFF","permalink":"/docs/practica-3"}}'),l=o(4848),r=o(8453);let c={id:"practica-4",title:"Practica 4: Navegaci\xf3n global con algoritmo GPP, plan como recurso",sidebar_position:4},s="Practica 4: Navegaci\xf3n global con algoritmo GPP, plan como recurso",i={},t=[];function d(e){let a={a:"a",h1:"h1",header:"header",p:"p",...(0,r.R)(),...e.components};return(0,l.jsxs)(l.Fragment,{children:[(0,l.jsx)(a.header,{children:(0,l.jsx)(a.h1,{id:"practica-4-navegaci\xf3n-global-con-algoritmo-gpp-plan-como-recurso",children:"Practica 4: Navegaci\xf3n global con algoritmo GPP, plan como recurso"})}),"\n",(0,l.jsx)(a.h1,{id:"objetivo",children:"Objetivo"}),"\n",(0,l.jsx)(a.p,{children:"El objetivo de la pr\xe1ctica es implementar la l\xf3gica de navegaci\xf3n global de un coche aut\xf3nomo que se mueve por un mapa de ciudad. Cuando el usuario selecciona un destino haciendo clic en el mapa, el algoritmo de planificaci\xf3n debe encontrar el camino m\xe1s corto hasta \xe9l, evitando todo lo que no sea carretera, y el robot debe seguir ese camino de forma aut\xf3noma hasta llegar. Para ello se utiliza el m\xe9todo Gradient Path Planning (GPP)"}),"\n",(0,l.jsx)(a.h1,{id:"desarrollo",children:"Desarrollo"}),"\n",(0,l.jsx)(a.p,{children:"Al arrancar se carga el mapa con WebGUI.getMap, que devuelve un array de NumPy en escala de grises. A partir de \xe9l se construye una m\xe1scara booleana de obst\xe1culos: las celdas con un valor menor o igual que un umbral se consideran no transitables. Esta m\xe1scara se calcula una sola vez, ya que el mapa no cambia durante la ejecuci\xf3n."}),"\n",(0,l.jsx)(a.p,{children:"Una vez se tiene la lectura del mapa se implementa la penalizaci\xf3n. Si el camino se calculara solo con la distancia, ir\xeda pegado a los bordes de la carretera y el coche chocar\xeda en las curvas. Por eso se calcula una matriz de penalizaci\xf3n que suma un coste extra a las celdas cercanas a un obst\xe1culo, mayor cuanto m\xe1s cerca est\xe1n y nulo a partir de cierto radio. Se calcula desplazando la m\xe1scara de obst\xe1culos sobre todos los desplazamientos posibles dentro del radio y qued\xe1ndose, en cada celda, con la penalizaci\xf3n del obst\xe1culo m\xe1s cercano. Se ejecuta una sola vez al inicio, porque solo depende del mapa."}),"\n",(0,l.jsx)(a.p,{children:"A continuaci\xf3n, se implementa el algoritmo Wave Front. Cuando se selecciona un destino nuevo se genera el campo de costes con una expansi\xf3n tipo Dijkstra desde el destino, usando una cola de prioridad. Cada celda se expande a sus 8 vecinos: el coste de un paso es 1 en los movimientos ortogonales y 1,4 en los diagonales, y a ello se suma la penalizaci\xf3n de la celda a la que se entra. Las celdas que son obst\xe1culo no se expanden. Como los costes no son todos iguales, una celda puede recibir primero un coste y despu\xe9s uno menor, por lo que se actualiza cuando se encuentra un valor mejor y se descartan las entradas obsoletas de la cola. El resultado es una matriz de costes de 400x400 en la que el destino vale 0 y el coste crece al alejarse de \xe9l, de modo que bajando por los valores decrecientes se llega al destino."}),"\n",(0,l.jsx)(a.p,{children:"En cada iteraci\xf3n del bucle principal, el coche obtiene su posici\xf3n con HAL.getPose3d y la convierte a una celda del mapa. Desde esa celda se desciende por el gradiente un n\xfamero fijo de pasos, eligiendo siempre la celda vecina de menor coste, y la celda obtenida se convierte en el punto objetivo local. Como el enunciado recomienda, el punto local se toma a una distancia suficiente para no perder las curvas. El control es proporcional. Se calcula el error entre el \xe1ngulo hacia el punto local y la orientaci\xf3n del coche, la velocidad angular es proporcional a ese error y la velocidad lineal disminuye al aumentar el error de giro, con un m\xednimo para que el coche no se detenga. Cuando la distancia al destino es menor que 3 m, el coche se detiene y el programa queda esperando a que se seleccione otro punto, sin terminar la ejecuci\xf3n. Al hacer clic en un nuevo destino se recalcula el campo y el coche vuelve a moverse."}),"\n",(0,l.jsx)(a.h1,{id:"problemas-encontrados",children:"Problemas encontrados"}),"\n",(0,l.jsx)(a.p,{children:"En una primera versi\xf3n, la matriz de costes era de tipo uint8 para poder mostrarla directamente. Esto truncaba los pesos decimales, el 1,4 de las diagonales pasaba a ser 1, y obligaba a limitar la expansi\xf3n a un coste de 250, con lo que las celdas m\xe1s lejanas quedaban sin valor y el coche pod\xeda quedarse parado. Para solucionarlo se us\xf3 una matriz de n\xfameros decimales con infinito como valor de celda sin asignar, y se convirti\xf3 a uint8 solo al mostrar la imagen, normalizando el coste."}),"\n",(0,l.jsx)(a.p,{children:"Durante el desarrollo de la pr\xe1ctica hubo problemas con el uso de coordenadas al trabajar con la rejilla. La funci\xf3n worldToGrid devuelve las coordenadas como (columna, fila), mientras que NumPy forma los arrays como [fila, columna]. Un error en esto hace que el campo se expanda por zonas equivocadas. Para solucionarlo se implementaron dos funciones, world_to_cell y cell_to_world, de modo que internamente todo el c\xf3digo trabaja con (fila, columna), y mostrar por la terminal las coordenadas del destino en el mundo y en la rejilla para comprobarlas."}),"\n",(0,l.jsx)(a.p,{children:"En las primeras simulaciones el coche se chocaba con las esquinas al girar. Esto se deb\xeda a que el punto local se eleg\xeda como la celda de menor coste dentro de una ventana alrededor del coche. En una curva, esa celda pod\xeda quedar al otro lado de la esquina, y la l\xednea recta hacia ella atravesaba la pared. Por lo que para solucionarlo, en lugar de buscar en una ventana, el punto local se obtiene bajando un n\xfamero fijo de celdas por el gradiente, de forma que siempre est\xe1 sobre un camino que sigue la carretera."}),"\n",(0,l.jsx)(a.p,{children:"Otro problema que se tuvo en las primeras simulaciones fue que al llegar al destino, el coche se pon\xeda a dar vueltas sobre si mismo hasta que se eligiese un nuevo destino. Al detectar la llegada se enviaban velocidad y giro cero, pero a continuaci\xf3n el programa ejecutaba igualmente el bloque de control y volv\xeda a enviar una velocidad y un giro. Estas \xf3rdenes contradictorias, junto con un punto local cada vez m\xe1s cercano que el coche sobrepasaba, hac\xedan que orbitara alrededor del destino. Para solucionarlo, al llegar se ponen a cero las velocidades y se salta el resto de la iteraci\xf3n, adem\xe1s se usa una variable para imprimir el aviso de llegada una sola vez. El coche queda quieto hasta que se elige un nuevo destino."}),"\n",(0,l.jsx)(a.h1,{id:"v\xeddeo",children:"V\xeddeo"}),"\n",(0,l.jsx)(a.p,{children:(0,l.jsx)(a.a,{href:"https://youtu.be/gxmLR7vwJHU",children:"https://youtu.be/gxmLR7vwJHU"})}),"\n",(0,l.jsx)(a.h1,{id:"conclusi\xf3n",children:"Conclusi\xf3n"}),"\n",(0,l.jsx)(a.p,{children:"La pr\xe1ctica permite comprobar c\xf3mo un algoritmo de planificaci\xf3n basado en un campo de potencial puede resolver la navegaci\xf3n global: el wavefront calcula en una sola pasada el coste de llegar al destino desde cualquier celda, y seguir el gradiente descendente produce un camino que evita los obst\xe1culos. La penalizaci\xf3n cerca de las paredes y un punto local situado unas celdas por delante resultaron clave para que el coche tomara bien las curvas."}),"\n",(0,l.jsx)(a.p,{children:"La soluci\xf3n cumple el objetivo de llegar al destino siguiendo el camino m\xe1s corto por la carretera, con una visualizaci\xf3n progresiva de la onda hasta el coche. Entre sus limitaciones est\xe1n el rec\xe1lculo completo del campo en cada destino nuevo, que bloquea el bucle durante unos instantes, y el lookahead fijo, que obliga a un compromiso entre las rectas y las curvas. Como posibles mejoras podr\xedan plantearse un lookahead adaptativo seg\xfan la curvatura del camino, el frenado antes de las curvas y optimizaciones en la expansi\xf3n para reducir el tiempo de c\xe1lculo."})]})}function u(e={}){let{wrapper:a}={...(0,r.R)(),...e.components};return a?(0,l.jsx)(a,{...e,children:(0,l.jsx)(d,{...e})}):d(e)}},8453(e,a,o){o.d(a,{R:()=>c,x:()=>s});var n=o(6540);let l={},r=n.createContext(l);function c(e){let a=n.useContext(r);return n.useMemo(function(){return"function"==typeof e?e(a):{...a,...e}},[a,e])}function s(e){let a;return a=e.disableParentContext?"function"==typeof e.components?e.components(l):e.components||l:c(e.components),n.createElement(r.Provider,{value:a},e.children)}}}]);